import{_ as a,a as s,b as i,c as l,d as p,e as t,f as m,g as r,h as c,i as o,j as n,k as d,l as f,m as h,n as g,o as u,p as b,q as x,r as k,s as j,t as v,u as _,v as X,w as S,x as y,y as R,z as w,A as E,B as F}from"./chunks/clip-mask.C6ARFJdO.js";import{_ as U,o as C,c as L,a2 as B}from"./chunks/framework.Ky-Ipuyb.js";const q=JSON.parse('{"title":"RmlUi サンプル","description":"","frontmatter":{"lang":"ja","sourcePath":"packages/sfml.js-rmlui/examples/README.ja.md"},"headers":[],"relativePath":"ja/examples/rmlui.md","filePath":"ja/examples/rmlui.md"}'),M={name:"ja/examples/rmlui.md"};function z(D,e,I,T,P,V){return C(),L("div",null,[...e[0]||(e[0]=[B('<h1 id="rmlui-サンプル" tabindex="-1">RmlUi サンプル <a class="header-anchor" href="#rmlui-サンプル" aria-label="Permalink to &quot;RmlUi サンプル&quot;">​</a></h1><p>ネイティブ SFML ウィンドウで RmlUi 文書を実行します。カウンターから始めて、テーマ、移動可能なウィンドウ、テンプレート、視覚テストへ進みます。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>すべてのコマンドは <strong>monorepo のルート</strong>で実行します。bootstrap は依存関係を導入し、各パッケージをビルドします。画面と OpenGL が必要です。macOS のビルドには Xcode Command Line Tools と CMake も必要です。<a href="/ja/rmlui/getting-started">クイックスタート</a>を参照してください。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span></code></pre></div><p>RmlUi の TypeScript ソースを変更したら、<code>npm run build:ts --prefix packages/sfml.js-rmlui</code> を実行します。サンプルはローカルでビルドしたパッケージを使います。</p><p>ランチャーはパッケージの <code>third_party/rmlui</code> にある RmlUi 6.3 同梱素材を読み込みます。全項目を一覧表示するには：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre></div><h2 id="サンプル一覧" tabindex="-1">サンプル一覧 <a class="header-anchor" href="#サンプル一覧" aria-label="Permalink to &quot;サンプル一覧&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="demo"><a href="/media/rmlui/examples/screenshots/demo.png"><img src="'+a+'" width="360" alt="カウンター、ぼかし、角丸クリッピング"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/demo.cjs">カウンター</a></strong></p><p>JavaScript リスナー、外部 RML、ぼかし、シャドウ、角丸クリッピング</p><p><code>node packages/sfml.js-rmlui/examples/demo.cjs</code></p><p><strong>操作</strong>：Increment で値を更新します。ウィンドウを閉じると終了します。</p><p><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/assets/tutorial.rml">RML</a> · <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/assets/tutorial.rcss">RCSS</a></p></div></article></div><article class="example-entry" id="variables"><a href="/media/rmlui/examples/screenshots/variables.png"><img src="'+s+'" width="360" alt="ダークテーマとミッションボタン"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/variables/main.cjs">テーマと変数</a></strong></p><p>テーマ切り替え、アクセントカラー、ホバースタイル</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs variables</code></p><p><strong>操作</strong>：1 はダーク、2 はライト、3 は高コントラスト、 R はランダムなアクセント、C はアクセントのリセットです。Escape で終了します。 ミッションボタンはホバー表示のみで、上流にはクリック処理がありません。 </p><p> 元のスタイルシートは固定の <code>px</code> 長を使います。 <code>highDpi: false</code> により Retina でも 1024 × 768 の フレームバッファーを保持し、上流のウィンドウサイズに合わせます。 F8 で Debugger を切り替え、Ctrl +/-/0 で Shell の表示密度を調整します。 </p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/variables/data/variables.rml">上流 RML</a></p></div></article><article class="example-entry" id="drag"><a href="/media/rmlui/examples/screenshots/drag.png"><img src="'+i+'" width="360" alt="2 つのインベントリウィンドウ"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/tutorial/drag/main.cjs">ドラッグチュートリアル</a></strong></p><p>移動・リサイズ可能なインベントリウィンドウ</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs drag</code></p><p><strong>操作</strong>：マウスで 2 つのウィンドウを移動・リサイズします。Escape で終了します。</p><p>チュートリアルのウィンドウ設定を移植したもので、上流の <code>basic/drag</code> アプリとは別です。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/tutorial/drag/data/inventory.rml">上流 RML</a></p></div></article><article class="example-entry" id="template"><a href="/media/rmlui/examples/screenshots/template.png"><img src="'+l+'" width="360" alt="テクスチャで装飾したウィンドウ"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/tutorial/template/main.cjs">テンプレートチュートリアル</a></strong></p><p>9 分割テクスチャと外部テンプレート</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs template</code></p><p><strong>操作</strong>：装飾されたウィンドウを確認します。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/tutorial/template/data/tutorial.rml">上流 RML</a></p></div></article><article class="example-entry" id="load-document"><a href="/media/rmlui/examples/screenshots/load-document.png"><img src="'+p+'" width="360" alt="上流の文書と素材"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/load_document/main.cjs">文書の読み込み</a></strong></p><p>元のテンプレート、フォント、テクスチャとともに上流の文書を読み込む</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs load-document</code></p><p><strong>操作</strong>：読み込んだ文書を確認します。Escape で終了します。他の上流デモのアプリ操作は接続していません。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/assets/demo.rml">上流 RML</a></p></div></article><article class="example-entry" id="font-effect"><a href="/media/rmlui/examples/screenshots/font-effect.png"><img src="'+t+'" width="360" alt="カスタムフォント効果で描画した緑色のテキスト"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/font-effect.cjs">カスタムフォント効果</a></strong></p><p>JavaScript の FontEffectInstancer とネイティブのグリフテクスチャコールバック</p><p><code>node packages/sfml.js-rmlui/examples/font-effect.cjs</code></p><p><strong>操作</strong>：Space でグロー効果を切り替え、Escape で終了します。</p><p>有限スモーク実行：<code>--frames N</code>、<code>--screenshot path.png</code> で最終フレームを保存します。</p></div></article><article class="example-entry" id="streams"><a href="/media/rmlui/examples/screenshots/streams.png"><img src="'+m+'" width="360" alt="三種類のネイティブバイトストリーム"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/streams.cjs">バイトストリーム</a></strong></p><p>ファイル文書、ネイティブメモリコピー、同期コールバックの RCSS 入力</p><p><code>node packages/sfml.js-rmlui/examples/streams.cjs</code></p><p><strong>操作</strong>：Escape で終了。<code>--frames N --screenshot path.png</code> で有限フレームを保存します。</p><p><a href="/ja/rmlui/streams">Stream API とライフサイクル</a></p></div></article><article class="example-entry" id="element-utilities"><a href="/media/rmlui/examples/screenshots/element-utilities.png"><img src="'+r+'" width="360" alt="クリップと配置を計測するネイティブ要素インスペクター"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/element-utilities.cjs">要素インスペクター</a></strong></p><p>四隅の配置、文字幅、投影境界、所有クリップジオメトリ</p><p><code>node packages/sfml.js-rmlui/examples/element-utilities.cjs</code></p><p><strong>操作</strong>：Space で次の隅、Escape で終了。</p><p><code>--frames 6 --exercise --screenshot path.png</code> で四隅を検証して撮影します。</p><p><a href="/ja/rmlui/element-utilities">要素ユーティリティとコピーの所有権</a></p><p><a href="/ja/rmlui/render-state">ネイティブジオメトリのクリップと描画状態復元</a></p></div></article><article class="example-entry" id="render-layers"><a href="/media/rmlui/examples/screenshots/render-layers.png"><img src="'+c+'" width="360" alt="ネイティブの入れ子合成、ガウスぼかし、位置付きアルファマスク"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/render-layers.cjs">レイヤー合成</a></strong></p><p>均衡したネイティブ層、乗算済みアルファ、自己合成フィルター、保存マスク</p><p><code>node packages/sfml.js-rmlui/examples/render-layers.cjs</code></p><p><strong>操作</strong>：Space で図形を移動、Escape で終了。</p><p><code>--frames 6 --exercise --screenshot path.png</code> で二つの位置と最終フレームを確認できます。</p><p><a href="/ja/rmlui/render-state#render-layers">レイヤーハンドル、フィルター所有権、マスク</a></p></div></article><article class="example-entry" id="callback-textures"><a href="/media/rmlui/examples/screenshots/callback-textures.png"><img src="'+o+'" width="360" alt="RGBA 生成、所有テクスチャ転送、ネイティブレイヤー保存"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/callback-textures.cjs">コールバックテクスチャ</a></strong></p><p>遅延乗算済みバイト生成、所有ハンドル転送、シザー領域のレイヤー保存</p><p><code>node packages/sfml.js-rmlui/examples/callback-textures.cjs</code></p><p><strong>操作</strong>：Space で色を再生成。Escape で終了。</p><p><code>--frames 6 --exercise --screenshot path.png</code> でキャッシュと再生成を確認し、最終フレームを保存します。</p><p><a href="/ja/rmlui/render-state#callback-textures">提出方法、寿命、所有権</a></p></div></article><article class="example-entry" id="factory-elements"><a href="/media/rmlui/examples/screenshots/factory-elements.png"><img src="'+n+'" width="360" alt="ネイティブ入力の生成と RML の子の解析"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/factory-elements.cjs">要素ファクトリー</a></strong></p><p>カスタムコンテキストと入力の生成・解放、所有文書ストリーム、独立タグと Factory キャッシュ</p><p><code>node packages/sfml.js-rmlui/examples/factory-elements.cjs</code></p><p><strong>操作</strong>：入力欄を編集、Space で更新、Escape で終了。</p><p><code>--frames 6 --exercise --screenshot path.png</code> で編集を検証し、最終フレームを撮影します。</p><p><a href="/ja/rmlui/resources#factory-の解析とキャッシュ">Factory の解析とキャッシュ</a></p><p><a href="/ja/rmlui/resources#要素生成器">要素生成器の所有権</a></p></div></article><article class="example-entry" id="data-models"><a href="/media/rmlui/examples/screenshots/data-models.png"><img src="'+d+'" width="360" alt="ネイティブモデル式と双方向コントロール"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/data-models.cjs">ネイティブデータモデル</a></strong></p><p>ネイティブスカラー、再帰 data-for、共有配列、部分更新、getter と変換、自作 Factory ビューと既定双方向コントローラーの委譲</p><p><code>node packages/sfml.js-rmlui/examples/data-models.cjs</code></p><p><strong>操作</strong>：Increment で計数更新、タイトル編集、詳細切替、Escape で終了。</p><p><code>--frames 6 --exercise --screenshot path.png</code> でバインドを検証し、最終フレームを撮影します。</p><p><a href="/ja/rmlui/data-models">データモデル契約と残りの範囲</a></p></div></article><article class="example-entry" id="data-binding"><a href="/media/rmlui/examples/screenshots/data-binding-events.png"><img src="'+f+'" width="360" alt="上流のイベントモデルと記録したマウス座標"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/data_binding/main.cjs">公式データバインディング</a></strong></p><p>Basics、Events、Invaders、Forms の四モデルで、ネイティブ式と同期配列変更を実行</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs data-binding</code></p><p><strong>操作</strong>：タブ切り替え、入力、マウス座標の記録と消去、項目の追加と削除、ゲーム開始と射撃。Escape で終了。</p><p><code>--frames 45 --exercise --panel invaders --screenshot path.png</code> は状態を検証し、選択したタブを撮影します。</p><p><a href="/media/rmlui/examples/screenshots/data-binding-basics.png">Basics</a> · <a href="/media/rmlui/examples/screenshots/data-binding-invaders.png">Invaders</a> · <a href="/media/rmlui/examples/screenshots/data-binding-forms.png">Forms</a></p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/data_binding/src/main.cpp">上流アプリケーション</a></p></div></article><article class="example-entry" id="basic-demo"><a href="/media/rmlui/examples/screenshots/basic-demo-sandbox.png"><img src="'+h+'" width="360" alt="元の RML と RCSS エディターで実際の入れ子文書を更新"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/demo/main.cjs">公式コントロールとサンドボックス</a></strong></p><p>元の六タブ、デコレーターと色の補間、フォーム、四秒の送信アニメーション、ライブ RML/RCSS エディター</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs basic-demo</code></p><p><strong>操作</strong>：タブ切り替え、補間設定、フォーム送信、サンドボックス編集。Escape は開いた選択欄を取消し、それ以外は終了します。F8 で Debugger を切り替えます。</p><p><code>--panel sandbox --frames 8 --exercise --screenshot path.png</code> は両エディターを検証し、サンドボックスを撮影します。パネル：welcome、decorators、font-effects、animations、controls、sandbox。</p><p><a href="/media/rmlui/examples/screenshots/basic-demo-controls.png">フォーム</a> · <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/demo/DemoWindow.cjs">ウィンドウ処理</a> · <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/demo/DemoEventListener.cjs">イベントリスナー</a></p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/demo/src/main.cpp">上流アプリケーション</a></p></div></article><article class="example-entry" id="tree-view"><a href="/media/rmlui/examples/screenshots/tree-view.png"><img src="'+g+'" width="360" alt="上流サンプルの実ディレクトリーツリー"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/tree_view/main.cjs">公式ツリービュー</a></strong></p><p>サンプルディレクトリーを走査し、FileBrowser の規則で子孫の表示を切り替え</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs tree-view</code></p><p><strong>操作</strong>：矢印をクリックして展開と折りたたみ。Escape で終了。</p><p><code>--frames 12 --exercise --screenshot path.png</code> は実ディレクトリーの切り替えを検証します。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/tree_view/src/FileBrowser.cpp">上流アプリケーション</a></p></div></article><article class="example-entry" id="animation"><a href="/media/rmlui/examples/screenshots/animation.png"><img src="'+u+'" width="360" alt="元の変換、混合単位、遷移アニメーション"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/animation/main.cjs">公式アニメーション</a></strong></p><p>元の変換列、色のキー、フェード周期、遷移とアニメーションイベント</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs animation</code></p><p><strong>操作</strong>：Space で停止、Return で一回実行、+/- で微調整、矢印でアニメーション、F8 で Debugger、Escape で終了。</p><p><code>--frames 8 --exercise --screenshot path.png</code> は停止、一回実行、クリックを検証して撮影します。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/animation/src/main.cpp">上流アプリケーション</a></p></div></article><article class="example-entry" id="benchmark"><a href="/media/rmlui/examples/screenshots/benchmark.png"><img src="'+b+'" width="360" alt="元のベンチマークの経路行、範囲入力と選択項目"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/benchmark/main.cjs">公式ベンチマーク</a></strong></p><p>更新ごとに元の 50 行を再生成し、独立した描画と 200 項目の FPS リングを維持</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs benchmark</code></p><p><strong>操作</strong>：Space で描画停止、Down で一回描画、Return で行更新停止、Right で一回更新、F8 で Debugger、Escape で終了。</p><p><code>--frames 3 --screenshot path.png</code> はフレーム数を限定して撮影します。</p><p><a href="https://github.com/mikke89/RmlUi/blob/6.3/Samples/basic/benchmark/src/main.cpp">上流アプリケーション</a></p></div></article><article class="example-entry" id="basic-drag"><a href="/media/rmlui/examples/screenshots/basic-drag.png"><img src="'+x+'" width="360" alt="二つのネイティブウィンドウの元のドラッグアイコン"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/drag/main.cjs">公式ドラッグ</a></strong></p><p>ネイティブ所有のアイコンをウィンドウ間で移動し、順序を変更します。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs basic-drag</code></p><p>アイコンを別のウィンドウや前のアイコンにドラッグします。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/drag">上流のアプリケーション</a></p></div></article><article class="example-entry" id="effects"><a href="/media/rmlui/examples/screenshots/effects.png"><img src="'+k+'" width="360" alt="元の効果コントロールとフィルター処理された内容"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/effects/main.cjs">公式エフェクト</a></strong></p><p>元の色フィルター、ぼかし、影、変換、不透明度を調整します。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs effects</code></p><p>メニューを開き、スライダーを調整するか設定をリセットします。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/effects">上流のアプリケーション</a></p></div></article><article class="example-entry" id="transform"><a href="/media/rmlui/examples/screenshots/transform.png"><img src="'+j+'" width="360" alt="元の正投影と透視変換"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/transform/main.cjs">公式変換</a></strong></p><p>元の文書を正投影と透視投影で回転させます。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs transform</code></p><p>Space で回転を一時停止し、Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/transform">上流のアプリケーション</a></p></div></article><article class="example-entry" id="svg"><a href="/media/rmlui/examples/screenshots/svg.png"><img src="'+v+'" width="360" alt="元の SVG 要素とデコレーター"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/svg/main.cjs">公式 SVG</a></strong></p><p>元の SVG 要素、デコレーター、インライン更新を描画します。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs svg</code></p><p>元の更新コントロールを操作します。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/svg">上流のアプリケーション</a></p></div></article><article class="example-entry" id="lottie"><a href="/media/rmlui/examples/screenshots/lottie.png"><img src="'+_+'" width="360" alt="ネイティブ rlottie で描画する元の山のアニメーション"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/lottie/main.cjs">公式 Lottie</a></strong></p><p>ネイティブのフレーム時刻とラスタライズで元の山のアニメーションを再生します。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs lottie</code></p><p>アニメーションは自動でループします。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/lottie">上流のアプリケーション</a></p></div></article><article class="example-entry" id="bitmap-font"><a href="/media/rmlui/examples/screenshots/bitmap-font.png"><img src="'+X+'" width="360" alt="元の Comfortaa ビットマップフォントアトラス"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/bitmap_font/main.cjs">公式ビットマップフォント</a></strong></p><p>元の FNT の送り幅、カーニング、ネイティブのアトラステクスチャを使います。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs bitmap-font</code></p><p>元の三つの段落を確認します。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/bitmap_font">上流のアプリケーション</a></p></div></article><article class="example-entry" id="harfbuzz"><a href="/media/rmlui/examples/screenshots/harfbuzz.png"><img src="'+S+'" width="360" alt="元の多言語 HarfBuzz テキストシェーピング"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/harfbuzz/main.cjs">公式 HarfBuzz</a></strong></p><p>元のフォントで英語、アラビア語、ヒンディー語の段落をシェーピングします。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs harfbuzz</code></p><p>言語ボタンで段落を切り替えます。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/harfbuzz">上流のアプリケーション</a></p></div></article><article class="example-entry" id="custom-log"><a href="/media/rmlui/examples/screenshots/custom-log.png"><img src="'+y+'" width="360" alt="アプリケーション独自のログインターフェイスを使う元の文書"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/custom_log/main.cjs">公式カスタムログ</a></strong></p><p>元のネイティブログメッセージとレベル接頭辞を指定ファイルに書き込みます。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs custom-log --log-file /tmp/rmlui-log.txt</code></p><p>既定のログはシステムの一時ディレクトリに保存します。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/custom_log">上流のアプリケーション</a></p></div></article><article class="example-entry" id="ime"><a href="/media/rmlui/examples/screenshots/ime.png"><img src="'+R+'" width="360" alt="絵文字と八言語の文章を含む元の IME フォーム"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/basic/ime/main.cjs">公式 IME</a></strong></p><p>元の十個のフォントを読み込み、ネイティブの入力欄とテキストエリアを開きます。</p><p>初回に五個の追加 Noto フォントを準備します（38 MB、SHA-256 検証）：<code>npm run download:ime-fonts --prefix packages/sfml.js-rmlui</code>。検証済みのキャッシュは再利用されます。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs ime</code></p><p>システムの入力方式を選び、入力欄にフォーカスします。Escape で終了します。</p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/basic/ime">上流のアプリケーション</a></p></div></article><article class="example-entry" id="invaders"><a href="/media/rmlui/examples/screenshots/invaders.png"><img src="'+w+'" width="360" alt="元の Invaders の編隊、防壁、自機とネイティブ HUD"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/invaders/main.cjs">Invaders</a></strong></p><p>元の C++ ゲーム、メニュー、デコレーターとハイスコアモデルを実行します。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs invaders</code></p><p>左右キーで移動、Space で発射、Escape で一時停止メニュー、F8 で Debugger を切り替えます。元のメニューから再開や終了を選択します。</p><p>先にパッケージをビルドしてください。ゲームモジュールは同じビルドディレクトリで生成され、読み込み時にコンパイラーは不要です。macOS は検証済み、Linux と Windows の実行は未検証です。</p><p>スコアはアプリのデータ領域に保存します。<code>--scores-file /absolute/path/scores.txt</code> は既存の親ディレクトリーを指定します。<code>--frames 8 --exercise</code> でフレーム数を制限して開始します。</p><p><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/invaders/native/application.cc">ネイティブ登録</a> · <a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/invaders">上流アプリ</a></p></div></article><article class="example-entry" id="lua-invaders"><a href="/media/rmlui/examples/screenshots/lua-invaders.png"><img src="'+E+'" width="360" alt="元の Lua Invaders のネイティブ編隊とスコア表示"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/lua_invaders/main.cjs">Lua Invaders</a></strong></p><p>元の Lua 文書と Game テーブルで元のネイティブゲームを動かします。</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs lua-invaders</code></p><p>左右キーで移動、Space で発射、Escape で一時停止メニュー、F8 で Debugger を切り替えます。設定はスコアファイルと同じ場所に保存します。</p><p>先にパッケージをビルドしてください。ゲームモジュールは同じビルドディレクトリで生成され、読み込み時にコンパイラーは不要です。macOS は検証済み、Linux と Windows の実行は未検証です。</p><p><code>--scores-file /absolute/path/scores.txt</code> は既存の親ディレクトリーを指定します。<code>--frames 8 --exercise</code> でフレーム数を制限して開始します。</p><p><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official/lua_invaders/native/application.cc">ネイティブ登録</a> · <a href="https://github.com/mikke89/RmlUi/tree/6.3/Samples/lua_invaders">上流アプリとスクリプト</a></p></div></article><article class="example-entry" id="visual-tests"><a href="/media/rmlui/examples/screenshots/clip-mask.png"><img src="'+F+'" width="360" alt="クリップマスクの視覚テスト"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-rmlui/examples/official.cjs">VisualTests ブラウザー</a></strong></p><p>上流の視覚テスト 113 ページを閲覧</p><p><code>node packages/sfml.js-rmlui/examples/official.cjs visual/clip_mask</code></p><p><strong>操作</strong>：F6 / F7 でページを切り替え、Escape で終了します。</p><p><code>--frames 60</code> を付けると 60 フレーム後に終了します。 <code>--frames N</code> は正の整数を受け取り、時間を限定したスモーク実行に使えます。 上流のアサーション機構を含まないプレビューです。 </p><p><a href="https://github.com/mikke89/RmlUi/tree/6.3/Tests/Data/VisualTests">上流 VisualTests</a> · <a href="/ja/rmlui/rendering">描画対応範囲</a></p></div></article><p>113 ページの VisualTests アサーション、実際の IME 検証、ゲームの残りのプラットフォーム対応、プロジェクト全体の独立した受け入れ検証は未完了です。描画とモジュールの検証結果は各ガイドに記録されています。画像は実行中のネイティブアプリケーションです。</p><p><a href="/ja/examples">全サンプル</a> · <a href="/ja/rmlui/getting-started">RmlUi クイックスタート</a></p>',40)])])}const G=U(M,[["render",z]]);export{q as __pageData,G as default};
